CREATE TABLE public.phone_pro_codes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code_hash text NOT NULL UNIQUE, target_user_id uuid NOT NULL REFERENCES public.profiles(id), expires_at timestamptz NOT NULL, issued_by uuid NOT NULL, issued_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.phone_pro_codes TO service_role;
ALTER TABLE public.phone_pro_codes ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.phone_code_devices (code_id uuid NOT NULL REFERENCES public.phone_pro_codes(id), device_id text NOT NULL, PRIMARY KEY(code_id,device_id));
GRANT ALL ON public.phone_code_devices TO service_role;
ALTER TABLE public.phone_code_devices ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.issue_phone_pro_code(_phone text,_expires_at timestamptz) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$ DECLARE u uuid; c text; BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Admin access required'; END IF; IF _expires_at<=now() OR _expires_at>now()+interval '1 year'+interval '1 day' THEN RAISE EXCEPTION 'Choose expiry within one year'; END IF; SELECT id INTO u FROM auth.users WHERE phone=regexp_replace(_phone,'[^0-9]','','g') AND phone_confirmed_at IS NOT NULL; IF u IS NULL THEN RAISE EXCEPTION 'Customer must create and verify their phone account first'; END IF; c:='PRO-'||upper(encode(gen_random_bytes(16),'hex')); INSERT INTO public.phone_pro_codes(code_hash,target_user_id,expires_at,issued_by) VALUES(encode(digest(c,'sha256'),'hex'),u,_expires_at,auth.uid()); RETURN c; END $$;
REVOKE ALL ON FUNCTION public.issue_phone_pro_code(text,timestamptz) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.issue_phone_pro_code(text,timestamptz) TO authenticated;
CREATE FUNCTION public.redeem_phone_pro_code(_code text,_device text) RETURNS timestamptz LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$ DECLARE c public.phone_pro_codes; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF; IF _device !~ '^[A-F0-9]{8}$' THEN RAISE EXCEPTION 'Invalid device'; END IF; PERFORM pg_advisory_xact_lock(hashtext(auth.uid()::text)); SELECT * INTO c FROM public.phone_pro_codes WHERE code_hash=encode(digest(upper(trim(_code)),'sha256'),'hex') FOR UPDATE; IF NOT FOUND OR c.target_user_id<>auth.uid() OR c.expires_at<=now() THEN RAISE EXCEPTION 'Invalid or expired code'; END IF; IF NOT EXISTS(SELECT 1 FROM public.phone_code_devices WHERE code_id=c.id AND device_id=_device) AND (SELECT count(*) FROM public.phone_code_devices WHERE code_id=c.id)>=2 THEN RAISE EXCEPTION 'This code is limited to two devices'; END IF; IF NOT EXISTS(SELECT 1 FROM public.pro_devices WHERE user_id=auth.uid() AND device_id=_device AND expires_at>now()) AND (SELECT count(*) FROM public.pro_devices WHERE user_id=auth.uid() AND expires_at>now())>=2 THEN RAISE EXCEPTION 'Already active on two devices'; END IF; INSERT INTO public.phone_code_devices(code_id,device_id) VALUES(c.id,_device) ON CONFLICT DO NOTHING; INSERT INTO public.pro_devices(user_id,device_id,expires_at) VALUES(auth.uid(),_device,c.expires_at) ON CONFLICT(user_id,device_id) DO UPDATE SET expires_at=greatest(public.pro_devices.expires_at,excluded.expires_at); RETURN c.expires_at; END $$;
REVOKE ALL ON FUNCTION public.redeem_phone_pro_code(text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.redeem_phone_pro_code(text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.create_dj_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,name,phone) VALUES(new.id,left(coalesce(new.raw_user_meta_data->>'name',new.raw_user_meta_data->>'full_name',''),60),left(coalesce(new.phone,new.raw_user_meta_data->>'phone',''),20)); RETURN new; END $$;
CREATE FUNCTION public.verified_dj_admin() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF new.phone='254745260364' AND new.phone_confirmed_at IS NOT NULL THEN INSERT INTO public.user_roles(user_id,role) VALUES(new.id,'admin') ON CONFLICT DO NOTHING; END IF; RETURN new; END $$;
CREATE TRIGGER verified_dj_admin_phone AFTER INSERT OR UPDATE OF phone,phone_confirmed_at ON auth.users FOR EACH ROW EXECUTE FUNCTION public.verified_dj_admin();
COMMENT ON FUNCTION public.issue_pro_code(uuid,text,integer) IS 'Legacy request/device codes; new phone-based subscriptions use issue_phone_pro_code.';